&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.28.0&lt;/Version&gt;
    &lt;Build&gt;5.28.314&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;1002&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT 
    p.CodSucursala,
    p.Anul,
    p.Luna,
    p.CodBeneficiar,

    UPPER(e.TipFisier) AS Fond,
    e.TipFisier,

    CASE 
        WHEN SUM(p.ContributiePersonala) &amp;lt;&amp;gt; SUM(p.ContributiePersonalaRetinuta)
        THEN &#39;row-diff&#39;
        ELSE &#39;&#39;
    END AS RowClass,

    e.Email,
    f.FileId,
    f.FileName,

    SUM(p.ContributiePersonala) AS TotalCP,
    SUM(p.ContributieAngajator) AS TotalCA,
    SUM(p.ContributieTotala) AS TotalCT,
    SUM(p.ContributiePersonalaRetinuta) AS TotalRetinut,
    SUM(p.ContributieAngajatorVirata) AS TotalAngajator,
    SUM(p.ContributieTotalaVirata) AS TotalVirat

FROM app.PensieFacultativa p

INNER JOIN app.PensieFacultativaEmail e 
    ON e.CodBeneficiar = p.CodBeneficiar

INNER JOIN Files f
    ON f.Folder = &#39;Salarizare/Export/PensiiFacultative/&#39;

    AND f.FileName =
        p.CodSucursala + &#39;_&#39; 
        + e.TipFisier + &#39;_&#39;
        + CAST(p.Luna AS VARCHAR)
        + CAST(p.Anul AS VARCHAR)
        + &#39;.csv&#39;

WHERE 
    p.Anul = @Anul
    AND p.Luna = @Luna
    AND p.CodSucursala = @CodSucursala
    AND p.ContributieTotalaVirata &amp;gt; 0

GROUP BY 
    p.CodSucursala,
    p.Anul,
    p.Luna,
    p.CodBeneficiar,
    e.TipFisier,
    e.Email,
    f.FileId,
    f.FileName&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;IdColumn&quot;:&quot;CodBeneficiar&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;CodSucursala&quot;,&quot;Name&quot;:&quot;CodSucursala&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Anul&quot;,&quot;Name&quot;:&quot;Anul&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Luna&quot;,&quot;Name&quot;:&quot;Luna&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;CodBeneficiar&quot;,&quot;Name&quot;:&quot;CodBeneficiar&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Fond&quot;,&quot;Name&quot;:&quot;Fond&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TipFisier&quot;,&quot;Name&quot;:&quot;TipFisier&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;RowClass&quot;,&quot;Name&quot;:&quot;RowClass&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Email&quot;,&quot;Name&quot;:&quot;Email&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;FileId&quot;,&quot;Name&quot;:&quot;FileId&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;FileName&quot;,&quot;Name&quot;:&quot;FileName&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalCP&quot;,&quot;Name&quot;:&quot;TotalCP&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalCA&quot;,&quot;Name&quot;:&quot;TotalCA&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalCT&quot;,&quot;Name&quot;:&quot;TotalCT&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalRetinut&quot;,&quot;Name&quot;:&quot;TotalRetinut&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalAngajator&quot;,&quot;Name&quot;:&quot;TotalAngajator&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TotalVirat&quot;,&quot;Name&quot;:&quot;TotalVirat&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null}]}&lt;/DataSource&gt;
    &lt;ShowTitle&gt;True&lt;/ShowTitle&gt;
    &lt;NoDataMessage&gt;No Data&lt;/NoDataMessage&gt;
    &lt;AditionalHtmlHeader /&gt;
    &lt;OnInitJs /&gt;
    &lt;OnRefreshJs /&gt;
    &lt;EnableEmbed&gt;False&lt;/EnableEmbed&gt;
    &lt;ShowCondition /&gt;
    &lt;SearchPlaceholder&gt;Search&lt;/SearchPlaceholder&gt;
    &lt;SearchDelayTime&gt;300&lt;/SearchDelayTime&gt;
    &lt;TableHeight /&gt;
    &lt;PagerStyle&gt;TouchFriendly&lt;/PagerStyle&gt;
    &lt;DisplayMode&gt;Always&lt;/DisplayMode&gt;
    &lt;PopupWidth /&gt;
    &lt;WidthCoordinate&gt;px&lt;/WidthCoordinate&gt;
    &lt;PopupName /&gt;
    &lt;PageSizes&gt;[12,24,48]&lt;/PageSizes&gt;
    &lt;DefaultPageSize&gt;12&lt;/DefaultPageSize&gt;
    &lt;IsDebug&gt;False&lt;/IsDebug&gt;
    &lt;SearchEnabled&gt;True&lt;/SearchEnabled&gt;
    &lt;ExactSearch&gt;False&lt;/ExactSearch&gt;
    &lt;HideEmptyGrid&gt;False&lt;/HideEmptyGrid&gt;
    &lt;LoadOnSearch&gt;False&lt;/LoadOnSearch&gt;
    &lt;HideTableHead&gt;False&lt;/HideTableHead&gt;
    &lt;EnableStickyHead&gt;False&lt;/EnableStickyHead&gt;
    &lt;ItemButtonPosition&gt;Right&lt;/ItemButtonPosition&gt;
    &lt;ItemButtonPositionInColumn&gt;Right&lt;/ItemButtonPositionInColumn&gt;
    &lt;ItemButtonGroupingOptions&gt;HorizontalAlign&lt;/ItemButtonGroupingOptions&gt;
    &lt;FiltersEnabled&gt;True&lt;/FiltersEnabled&gt;
    &lt;ShowFilters&gt;False&lt;/ShowFilters&gt;
    &lt;SyncUrl&gt;False&lt;/SyncUrl&gt;
    &lt;IncludeBootstrapJS&gt;True&lt;/IncludeBootstrapJS&gt;
    &lt;IncludeBootstrapCSS&gt;True&lt;/IncludeBootstrapCSS&gt;
    &lt;IncludeFontAwesome&gt;True&lt;/IncludeFontAwesome&gt;
    &lt;AngularnoConflict&gt;True&lt;/AngularnoConflict&gt;
    &lt;SelectAllPosition&gt;None&lt;/SelectAllPosition&gt;
    &lt;SearchPosition&gt;top&lt;/SearchPosition&gt;
    &lt;RootCSSClasses /&gt;
    &lt;ModalRefresh&gt;False&lt;/ModalRefresh&gt;
    &lt;ShowLoading&gt;True&lt;/ShowLoading&gt;
    &lt;TabsProLoading&gt;True&lt;/TabsProLoading&gt;
    &lt;EnableGridSelect&gt;True&lt;/EnableGridSelect&gt;
    &lt;DataSourceAutoRefreshInterval&gt;1&lt;/DataSourceAutoRefreshInterval&gt;
    &lt;DataSourceRefreshType&gt;manual&lt;/DataSourceRefreshType&gt;
    &lt;DateFormat&gt;m/d/yy&lt;/DateFormat&gt;
    &lt;ItemButtonGroups&gt;[]&lt;/ItemButtonGroups&gt;
    &lt;GridButtonGroups&gt;[]&lt;/GridButtonGroups&gt;
    &lt;ItemButtons&gt;[{&quot;ItemActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;51db6502-a426-46d4-9442-ceab770b06b4&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RedirectToUrl&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Url&quot;:&quot;[Helper:FileData(FileId=[FileId])]&quot;,&quot;EscapeUrl&quot;:false,&quot;OpenInPopup&quot;:false,&quot;PopupTitle&quot;:null,&quot;OpenInNewTab&quot;:false,&quot;ForceDownload&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}}],&quot;OnItemClickActionStackId&quot;:-1,&quot;Url&quot;:&quot;&amp;amp;buttonName=Download&quot;,&quot;ModuleId&quot;:1002,&quot;AutoName&quot;:true,&quot;Name&quot;:&quot;Download&quot;,&quot;Title&quot;:&quot;Download&quot;,&quot;Help&quot;:null,&quot;ShowCondition&quot;:null,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{},&quot;Type&quot;:&quot;ItemButton&quot;,&quot;OrderIndex&quot;:0,&quot;CssClass&quot;:&quot;primary&quot;,&quot;CustomCssClass&quot;:&quot;btn btn-custom-blue&quot;,&quot;IconClass&quot;:&quot;&quot;,&quot;FaIconClass&quot;:&quot;float-start fas fa-download&quot;,&quot;PermissionAllUsers&quot;:true,&quot;PermissionsExportJson&quot;:&quot;[]&quot;,&quot;Permissions&quot;:[],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:&quot;Are you sure you want to do this?&quot;,&quot;ConfirmationOk&quot;:&quot;Yes, pretty sure&quot;,&quot;ConfirmationCancel&quot;:&quot;No, I&#39;m having second thoughts&quot;,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false}]&lt;/ItemButtons&gt;
    &lt;GridButtons&gt;[{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;969d470c-4d15-4918-b727-f5871f37d65b&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;1&quot;,&quot;EntireGroup&quot;:false,&quot;Entry&quot;:&quot;96750a11-0461-4f93-b8c3-73831454ac76&quot;},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;WITH BaseData AS (
    SELECT 
        p.CodBeneficiar as Id,
        p.CodBeneficiar,
        p.CodSucursala,
        ns.DenumireSucursala,
        p.Anul,
        p.Luna,
        r.DenumireBeneficiar,
        UPPER(e.TipFisier) AS TipFisier,
        e.Email,

        SUM(p.ContributiePersonala) AS TotalCP,
        SUM(p.ContributieAngajator) AS TotalCA,
        SUM(p.ContributieTotala) AS TotalCT,

        SUM(p.ContributiePersonalaRetinuta) AS TotalRetinut,
        SUM(p.ContributieAngajatorVirata) AS TotalAngajatorVirat,
        SUM(p.ContributieTotalaVirata) AS TotalVirat,

        SUM(p.ContributiePersonala) 
            - SUM(p.ContributiePersonalaRetinuta) AS Diferenta,

        CASE 
            WHEN SUM(p.ContributiePersonala) &amp;lt;&amp;gt; SUM(p.ContributiePersonalaRetinuta)
                THEN &#39;DIFERENTA&#39;
            ELSE &#39;OK&#39;
        END AS Status

    FROM app.PensieFacultativa p

    LEFT JOIN app.PensieFacultativaEmail e 
        ON e.CodBeneficiar = p.CodBeneficiar
    Join app.Sucursala ns on ns.CodSucursala=p.CodSucursala
    JOIN (
        SELECT 
            CodBeneficiar,
            CodSucursala,
            MAX(DenumireBeneficiar) AS DenumireBeneficiar
        FROM app.NomBeneficiarRetinere
        WHERE tiprataold = 7
        GROUP BY CodBeneficiar, CodSucursala
    ) r
        ON p.CodBeneficiar = r.CodBeneficiar
       AND p.CodSucursala = r.CodSucursala

    WHERE 
        p.Anul = @Anul
        AND p.Luna = @Luna
        AND p.CodSucursala = @CodSucursala
        AND p.ContributieTotalaVirata &amp;gt; 0

    GROUP BY 
        p.CodBeneficiar,
        p.CodSucursala,
        ns.DenumireSucursala,
        p.Anul,
        p.Luna,
        r.DenumireBeneficiar,
        e.TipFisier,
        e.Email
),

FinalData AS (
    SELECT 
        b.CodBeneficiar,
        b.CodSucursala,
  b.DenumireSucursala,
        b.Anul,
        b.Luna,
        b.DenumireBeneficiar,
        b.TotalCP,
        b.TotalCA,
        b.TotalCT,
        b.TotalRetinut,
        b.TotalAngajatorVirat,
        b.TotalVirat,
        b.Diferenta,
        b.Status,

        SUM(b.TotalCP) OVER() AS SumTotalCP,
        SUM(b.TotalCA) OVER() AS SumTotalCA,
        SUM(b.TotalCT) OVER() AS SumTotalCT

    FROM BaseData b
)

SELECT TOP 1

    Anul,
    Luna,
  CodSucursala,
    DenumireSucursala,

    SumTotalCP,
    SumTotalCA,
    SumTotalCT,
(
   SELECT 
    &#39;
    &amp;lt;tr&amp;gt;

        &amp;lt;td style=\&quot;border:1px solid #000; padding:4px 6px;\&quot;&amp;gt;
            &#39; + ISNULL(DenumireBeneficiar,&#39;&#39;) + &#39;
        &amp;lt;/td&amp;gt;

        &amp;lt;td style=\&quot;
            border:1px solid #000;
            padding:4px 6px;
            text-align:right;
        \&quot;&amp;gt;
            &#39; + CAST(ISNULL(TotalRetinut,0) AS VARCHAR) + &#39;
        &amp;lt;/td&amp;gt;

        &amp;lt;td style=\&quot;
            border:1px solid #000;
            padding:4px 6px;
            text-align:right;
        \&quot;&amp;gt;
            &#39; + CAST(ISNULL(TotalAngajatorVirat,0) AS VARCHAR) + &#39;
        &amp;lt;/td&amp;gt;

        &amp;lt;td style=\&quot;
            border:1px solid #000;
            padding:4px 6px;
            text-align:right;
        \&quot;&amp;gt;
            &#39; + CAST(ISNULL(TotalVirat,0) AS VARCHAR) + &#39;
        &amp;lt;/td&amp;gt;

    &amp;lt;/tr&amp;gt;
    &#39;
FROM FinalData
ORDER BY DenumireBeneficiar
FOR XML PATH(&#39;&#39;), TYPE
).value(&#39;.&#39;, &#39;NVARCHAR(MAX)&#39;)

AS RowsHtml
FROM FinalData&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;MyList&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false,&quot;UseTransactions&quot;:true},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;0b6bb7a8-1010-4644-b8c5-94fe29e7d1e5&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;HTMLtoWord&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;HTML&quot;:&quot;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html&amp;gt;

&amp;lt;head&amp;gt;
&amp;lt;meta charset=\&quot;UTF-8\&quot;&amp;gt;
&amp;lt;/head&amp;gt;

&amp;lt;body style=\&quot;font-family:Calibri, Arial, sans-serif; font-size:11pt; margin:40px; color:#000;\&quot;&amp;gt;

&amp;lt;div style=\&quot;width:100%;\&quot;&amp;gt;

    &amp;lt;!-- HEADER --&amp;gt;

    &amp;lt;div style=\&quot;position:relative; width:100%; height:80px;\&quot;&amp;gt;

        &amp;lt;div style=\&quot;
            position:absolute;
            left:0;
            top:0;
            text-align:left;
            line-height:1.5;
            font-weight:bold;
        \&quot;&amp;gt;
            C.N. POȘTA ROM&#194;NĂ S.A.&amp;lt;br&amp;gt;

            [MyList:DenumireSucursala] 
            COD: [MyList:CodSucursala]
        &amp;lt;/div&amp;gt;

        &amp;lt;div style=\&quot;
            position:absolute;
            right:0;
            top:0;
            text-align:right;
            font-weight:bold;
        \&quot;&amp;gt;
            DATA: [DateTime:Now]
        &amp;lt;/div&amp;gt;

    &amp;lt;/div&amp;gt;

    &amp;lt;!-- TITLU --&amp;gt;

    &amp;lt;div style=\&quot;
        text-align:center;
        font-size:14pt;
        margin-bottom:10px;
    \&quot;&amp;gt;
        CENTRALIZATOR FONDURI PENSII FACULTATIVE
    &amp;lt;/div&amp;gt;

    &amp;lt;!-- SUBTITLU --&amp;gt;

    &amp;lt;div style=\&quot;
        text-align:center;
        font-size:11pt;
